def handle_check_failure(result):
    severity = "P1" if result.dataset in CRITICAL else "P3"
    payload = {
        "dataset": result.dataset,
        "check": result.check_name,
        "observed": result.observed_value,
        "expected": result.threshold,
        "severity": severity,
    }
    if severity == "P1":
        pagerduty.trigger(payload)
    else:
        slack.post("#data-quality", payload)
